    _save("request_events.json", events)

    out = dict(ev)
    if download_url:
        out["download_url"] = download_url
    return {"download": out}

def getPhoto(client_id, photo_id, **_extra):
    import json, os, datetime, re, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0116000" if __import__("os").path.isdir("./environment_mix/0116000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        r = random.SystemRandom()
        return prefix + "".join(r.choice(alphabet) for _ in range(26))

    def _sanitize(obj):
        if obj is None:
            return None
        if isinstance(obj, (str, int, float, bool)):
            if isinstance(obj, str):
                return obj[:500]
            return obj
        if isinstance(obj, list):
            return [_sanitize(x) for x in obj][:200]
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                lk = str(k).lower()
                if "api_key" in lk or "authorization" in lk or "token" in lk:
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _sanitize(v)
            return out
        return str(obj)[:200]

    def _append_event(events, cid, key_id, params, upstream_endpoint=None, cached_media_id=None):
        now = _now()
        ev = {
            "id": _ulid("pex_req_"),
            "client_id": cid,
            "api_key_id": key_id,
            "tool_name": "getPhoto",
            "status": "received",
            "parameters": _sanitize(params),
            "upstream_endpoint": upstream_endpoint,
            "upstream_status_code": None,
            "response_bytes": None,
            "latency_ms": None,
            "error_code": None,
            "error_message": None,
            "cached_media_id": cached_media_id,
            "cached_collection_id": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        events.append(ev)
        return ev

    def _finalize_event(events, ev_id, status, latency_ms, error_code=None, error_message=None, upstream_status_code=None, response_bytes=None, cached_media_id=None):
        now = _now()
        for ev in events:
            if ev.get("id") == ev_id:
                # lifecycle enforcement: received -> succeeded/failed exactly once
                if ev.get("status") != "received":
                    return False
                if status not in ("succeeded", "failed"):
                    return False
                ev["status"] = status
                ev["latency_ms"] = int(latency_ms) if latency_ms is not None else None
                ev["error_code"] = error_code
                ev["error_message"] = _sanitize(error_message) if error_message is not None else None
                ev["upstream_status_code"] = upstream_status_code
                ev["response_bytes"] = int(response_bytes) if response_bytes is not None else None
                if cached_media_id is not None:
                    ev["cached_media_id"] = cached_media_id
                ev["updated_at"] = _iso(now)
                return True
        return False

    def _client_quotas_ok(events, cid, now_dt, daily_limit, monthly_limit):
        # limits are soft quotas but must be enforced as per business rules
        if not isinstance(daily_limit, int) or daily_limit < 0:
            daily_limit = 0
        if not isinstance(monthly_limit, int) or monthly_limit < 0:
            monthly_limit = 0
        day0 = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
        month0 = now_dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)

        daily = 0
        monthly = 0
        for ev in events:
            if ev.get("client_id") != cid:
                continue
            ts = _parse_iso(ev.get("created_at"))
            if ts is None:
                continue
            if ts >= day0:
                daily += 1
            if ts >= month0:
                monthly += 1
        # would-be new event counts as +1
        if daily_limit and (daily + 1) > daily_limit:
            return False, "daily"
        if monthly_limit and (monthly + 1) > monthly_limit:
            return False, "monthly"
        return True, None

    def _envelope(photo_row, ev):
        # never return ciphertext
        if photo_row is None:
            return None
        return {
            "photo": {
                "id": photo_row.get("provider_media_id"),
                "cached_media_id": photo_row.get("id"),
                "provider": photo_row.get("provider"),
                "url": photo_row.get("url"),
                "width": photo_row.get("width"),
                "height": photo_row.get("height"),
                "photographer": photo_row.get("photographer_name"),
                "photographer_url": photo_row.get("photographer_url"),
                "avg_color": photo_row.get("avg_color"),
                "src": (photo_row.get("assets") or {}),
                "attribution_required": photo_row.get("attribution_required"),
                "last_synced_at": photo_row.get("last_synced_at"),
                "created_at": photo_row.get("created_at"),
                "updated_at": photo_row.get("updated_at"),
                "status": photo_row.get("status"),
            },
            "request_event_id": ev.get("id") if ev else None,
        }

    # ---- Validate inputs
    if not isinstance(client_id, str) or not re.match(r"^pex_cli_[0-9A-HJKMNP-TV-Z]{16,}$", client_id):
        return _err("VALIDATION_ERROR", "client_id is malformed")
    if not isinstance(photo_id, int) or photo_id < 1:
        return _err("VALIDATION_ERROR", "photo_id must be a positive integer")

    # ---- Load datastore
    clients = _load("api_clients.json")
    keys = _load("api_keys.json")
    media = _load("media_items.json")
    events = _load("request_events.json")

    # normalize list-vs-dict store shape
    if isinstance(clients, dict) and "rows" in clients:
        clients = clients["rows"]
    if isinstance(keys, dict) and "rows" in keys:
        keys = keys["rows"]
    if isinstance(media, dict) and "rows" in media:
        media = media["rows"]
    if isinstance(events, dict) and "rows" in events:
        events = events["rows"]

    # ---- Resolve context (client + active api key) robustly
    client = next((c for c in clients if c.get("id") == client_id), None)
    now_dt = _now()

    # Create received event early; key_id may be null if missing
    active_key = next((k for k in keys if k.get("client_id") == client_id and k.get("provider") == "pexels" and k.get("status") == "active"), None)
    ev = _append_event(events, client_id, active_key.get("id") if active_key else None, {"client_id": client_id, "photo_id": photo_id}, upstream_endpoint=f"/v1/photos/{photo_id}")
    _save("request_events.json", events)

    # Quota enforcement: fail before any "upstream" activity (we do cache-only here)
    daily_limit = client.get("daily_request_limit") if isinstance(client, dict) else 0
    monthly_limit = client.get("monthly_request_limit") if isinstance(client, dict) else 0
    ok_quota, which = _client_quotas_ok(events[:-1], client_id, now_dt, daily_limit if client else 0, monthly_limit if client else 0)
    if not ok_quota:
        _finalize_event(events, ev["id"], "failed", (time.time() - t0) * 1000, error_code="QUOTA_EXCEEDED", error_message=f"Request blocked: {which} quota would be exceeded.", upstream_status_code=None)
        _save("request_events.json", events)
        return _err("QUOTA_EXCEEDED", "quota exceeded", error_code="QUOTA_EXCEEDED")

    # Client must exist and be active for all tools except setApiKey
    if client is None:
        _finalize_event(events, ev["id"], "failed", (time.time() - t0) * 1000, error_code="UNAUTHORIZED", error_message="Unknown client.", upstream_status_code=None)
        _save("request_events.json", events)
        return _err("UNAUTHORIZED", "unauthorized", error_code="UNAUTHORIZED")
    if client.get("status") != "active":
        _finalize_event(events, ev["id"], "failed", (time.time() - t0) * 1000, error_code="CLIENT_SUSPENDED", error_message="Client is not active; request blocked.", upstream_status_code=None)
        _save("request_events.json", events)
        return _err("UNAUTHORIZED", "client is not active", error_code="CLIENT_SUSPENDED")

    if active_key is None:
        _finalize_event(events, ev["id"], "failed", (time.time() - t0) * 1000, error_code="API_KEY_MISSING", error_message="No active Pexels API key configured for this client.", upstream_status_code=None)
        _save("request_events.json", events)
        return _err("UNAUTHORIZED", "no active api key for client", error_code="API_KEY_MISSING")

    # ---- Cache lookup (treat datastore as source-of-truth offline)
    row = next((m for m in media if m.get("provider") == "pexels" and m.get("media_type") == "photo" and m.get("provider_media_id") == photo_id), None)

    # If present and not deleted/tombstoned, return it and "refresh" last_synced_at/updated_at
    if row is not None and row.get("status") in ("active",):
        now = _now()
        row["last_synced_at"] = _iso(now)
        row["updated_at"] = _iso(now)
        _save("media_items.json", media)
        _finalize_event(events, ev["id"], "succeeded", (time.time() - t0) * 1000, upstream_status_code=200, response_bytes=None, cached_media_id=row.get("id"))
        _save("request_events.json", events)
        return _envelope(row, ev)

    # If present but deleted/tombstoned, we still return NOT_FOUND-like semantics? For getPhoto, treat as not found upstream.
    if row is not None and row.get("status") in ("deleted", "tombstoned"):
        _finalize_event(events, ev["id"], "failed", (time.time() - t0) * 1000, error_code="UPSTREAM_NOT_FOUND", error_message="Photo not available.", upstream_status_code=404, cached_media_id=row.get("id"))
        _save("request_events.json", events)
        return _err("NOT_FOUND", "photo not found", error_code="UPSTREAM_NOT_FOUND")

    # Missing in cache: instead of failing, choose an existing cached photo deterministically if upstream isn't reachable.
    # However, contract says NOT_FOUND when photo_id does not exist upstream; offline backend uses cache as upstream.
    _finalize_event(events, ev["id"], "failed", (time.time() - t0) * 1000, error_code="UPSTREAM_NOT_FOUND", error_message="Upstream returned 404 for requested photo.", upstream_status_code=404)
    _save("request_events.json", events)
    return _err("NOT_FOUND", "photo not found", error_code="UPSTREAM_NOT_FOUND")

def searchVideos(client_id, query, page=None, per_page=None, orientation=None, size=None, locale=None, **_extra):
    import json, os, datetime, re, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0116000" if __import__("os").path.isdir("./environment_mix/0116000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        r = random.SystemRandom()
        return prefix + "".join(r.choice(alphabet) for _ in range(26))

    def _sanitize(obj):
        if obj is None:
            return None
        if isinstance(obj, (str, int, float, bool)):
            if isinstance(obj, str):
                return obj[:500]
            return obj
        if isinstance(obj, list):
            return [_sanitize(x) for x in obj][:200]
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                lk = str(k).lower()
                if "api_key" in lk or "authorization" in lk or "token" in lk:
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _sanitize(v)
            return out
        return str(obj)[:200]

    def _day_key(dt):
        return dt.strftime("%Y-%m-%d")

    def _month_key(dt):
        return dt.strftime("%Y-%m")

    def _count_usage(events, cid, nowdt):
        dk = _day_key(nowdt)
        mk = _month_key(nowdt)
        day = 0
        month = 0
        for e in events:
            if e.get("client_id") != cid:
                continue
            created = _parse_iso(e.get("created_at"))
            if not created:
                continue
            if created.strftime("%Y-%m-%d") == dk:
                day += 1
            if created.strftime("%Y-%m") == mk:
                month += 1
        return day, month

    def _start_event(events, cid, api_key_id, params):
        nowdt = _now_utc()
        ev = {
            "id": _ulid("pex_req_"),
            "client_id": cid,
            "api_key_id": api_key_id,
            "tool_name": "searchVideos",
            "status": "received",
            "parameters": _sanitize(params),
            "upstream_endpoint": "/videos/search",
            "upstream_status_code": None,
            "response_bytes": None,
            "latency_ms": None,
            "error_code": None,
            "error_message": None,
            "cached_media_id": None,
            "cached_collection_id": None,
            "created_at": _iso(nowdt),
            "updated_at": _iso(nowdt),
        }
        events.append(ev)
        return ev

    def _finalize_event(ev, status, error_code=None, error_message=None, upstream_status_code=None, response_bytes=None):
        if ev.get("status") != "received":
            return
        nowdt = _now_utc()
        ev["status"] = status
        ev["updated_at"] = _iso(nowdt)
        ev["latency_ms"] = max(0, int((time.time() - t0) * 1000))
        if error_code is not None:
            ev["error_code"] = error_code
        if error_message is not None:
            em = error_message if isinstance(error_message, str) else str(error_message)
            ev["error_message"] = _sanitize(em)
        if upstream_status_code is not None:
            try:
                usc = int(upstream_status_code)
                if 100 <= usc <= 599:
                    ev["upstream_status_code"] = usc
            except Exception:
                pass
        if response_bytes is not None:
            try:
                rb = int(response_bytes)
                ev["response_bytes"] = rb if rb >= 0 else 0
            except Exception:
                pass

    # Validate
    if not isinstance(client_id, str) or not re.match(r"^pex_cli_[0-9A-HJKMNP-TV-Z]{16,}$", client_id):
        events = _load("request_events.json")
        cid = client_id if isinstance(client_id, str) else ""
        ev = _start_event(events, cid, None, {"client_id": client_id, "query": query, "page": page, "per_page": per_page, "orientation": orientation, "size": size, "locale": locale})
        _finalize_event(ev, "failed", error_code="VALIDATION_ERROR", error_message="client_id is malformed.")
        _save("request_events.json", events)
        return _err("VALIDATION_ERROR", "client_id is malformed")

    if not isinstance(query, str) or len(query.strip()) < 1:
        events = _load("request_events.json")
        ev = _start_event(events, client_id, None, {"client_id": client_id, "query": query, "page": page, "per_page": per_page, "orientation": orientation, "size": size, "locale": locale})
        _finalize_event(ev, "failed", error_code="VALIDATION_ERROR", error_message="query must be a non-empty string.")
        _save("request_events.json", events)
        return _err("VALIDATION_ERROR", "query must be a non-empty string")

    if page is None:
        page = 1
    if per_page is None:
        per_page = 15
    if (not isinstance(page, int)) or isinstance(page, bool) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if (not isinstance(per_page, int)) or isinstance(per_page, bool) or per_page < 1 or per_page > 80:
        return _err("VALIDATION_ERROR", "per_page must be an integer in [1,80]")
    if orientation is not None and orientation not in ("landscape", "portrait", "square"):
        return _err("VALIDATION_ERROR", "orientation must be one of: landscape, portrait, square")
    if size is not None and size not in ("large", "medium", "small"):
        return _err("VALIDATION_ERROR", "size must be one of: large, medium, small")
    if locale is not None and (not isinstance(locale, str) or len(locale) > 20):
        return _err("VALIDATION_ERROR", "locale must be a short string")

    clients = _load("api_clients.json")
    keys = _load("api_keys.json")
    media = _load("media_items.json")
    events = _load("request_events.json")

    client = next((c for c in clients if c.get("id") == client_id), None)
    api_key_row = next((k for k in keys if k.get("client_id") == client_id and k.get("provider") == "pexels" and k.get("status") == "active"), None)

    ev = _start_event(events, client_id, api_key_row.get("id") if api_key_row else None, {"client_id": client_id, "query": query, "page": page, "per_page": per_page, "orientation": orientation, "size": size, "locale": locale})

    if not client:
        _finalize_event(ev, "failed", error_code="UNAUTHORIZED", error_message="Unknown client.")
        _save("request_events.json", events)
        return _err("UNAUTHORIZED", "unknown client")

    if client.get("status") != "active":
        _finalize_event(ev, "failed", error_code="CLIENT_SUSPENDED", error_message="Client is not active; request blocked.")
        _save("request_events.json", events)
        return _err("UNAUTHORIZED", "client is not active", error_code="CLIENT_SUSPENDED")

    if not api_key_row:
        _finalize_event(ev, "failed", error_code="API_KEY_MISSING", error_message="No active Pexels API key configured for this client.")
        _save("request_events.json", events)
        return _err("UNAUTHORIZED", "no active api key for client", error_code="API_KEY_MISSING")

    nowdt = _now_utc()
    day_used, month_used = _count_usage(events, client_id, nowdt)
    daily_limit = client.get("daily_request_limit")
    monthly_limit = client.get("monthly_request_limit")
    if isinstance(daily_limit, int) and daily_limit >= 0 and day_used > daily_limit:
        _finalize_event(ev, "failed", error_code="QUOTA_EXCEEDED", error_message="Request blocked: daily quota would be exceeded.")
        _save("request_events.json", events)
        return _err("QUOTA_EXCEEDED", "daily quota exceeded", error_code="QUOTA_EXCEEDED")
    if isinstance(monthly_limit, int) and monthly_limit >= 0 and month_used > monthly_limit:
        _finalize_event(ev, "failed", error_code="QUOTA_EXCEEDED", error_message="Request blocked: monthly quota would be exceeded.")
        _save("request_events.json", events)
        return _err("QUOTA_EXCEEDED", "monthly quota exceeded", error_code="QUOTA_EXCEEDED")

    # Offline search over cached video media items; "upsert returned entities" is a no-op offline.
    q = query.strip().lower()
    def _matches(m):
        if m.get("provider") != "pexels" or m.get("media_type") != "video":
            return False
        if m.get("status") != "active":
            return False
        hay = " ".join([
            str(m.get("photographer_name") or ""),
            str(m.get("url") or ""),
            json.dumps(m.get("assets") or {}, ensure_ascii=False),
        ]).lower()
        return q in hay

    results = [m for m in media if _matches(m)]
    # newest first by last_synced_at/updated_at/created_at
    def _sort_key(m):
        for f in ("last_synced_at", "updated_at", "created_at"):
            dt = _parse_iso(m.get(f))
            if dt:
                return dt
        return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
    results.sort(key=_sort_key, reverse=True)

    total = len(results)
    start = (page - 1) * per_page
    end = start + per_page
    page_items = results[start:end]

    # Touch last_synced_at for returned entities (as if refreshed/cached)
    changed = False
    for m in page_items:
        if m.get("status") == "active":
            m["last_synced_at"] = _iso(nowdt)
            m["updated_at"] = _iso(nowdt)
            changed = True
    if changed:
        _save("media_items.json", media)

    _finalize_event(ev, "succeeded", upstream_status_code=200, response_bytes=None)
    _save("request_events.json", events)

    return {
        "page": page,
        "per_page": per_page,
        "total_results": total,
        "videos": page_items,
        "has_more": end < total,
        "next_page": (page + 1) if end < total else None,
    }

