    ev = _start_event(events, client_id, api_key_row.get("id") if api_key_row else None, {"client_id": client_id, "page": page, "per_page": per_page, "min_width": min_width, "min_height": min_height, "min_duration": min_duration, "max_duration": max_duration})

    if not client:
        _finalize_event(ev, "failed", error_code="UNAUTHORIZED", error_message="Unknown client.")
        _save("request_events.json", events)
        return _err("UNAUTHORIZED", "unknown client")

    if client.get("status") != "active":
        _finalize_event(ev, "failed", error_code="CLIENT_SUSPENDED", error_message="Client is not active; request blocked.")
        _save("request_events.json", events)
        return _err("UNAUTHORIZED", "client is not active", error_code="CLIENT_SUSPENDED")

    if not api_key_row:
        _finalize_event(ev, "failed", error_code="API_KEY_MISSING", error_message="No active Pexels API key configured for this client.")
        _save("request_events.json", events)
        return _err("UNAUTHORIZED", "no active api key for client", error_code="API_KEY_MISSING")

    nowdt = _now_utc()
    day_used, month_used = _count_usage(events, client_id, nowdt)
    daily_limit = client.get("daily_request_limit")
    monthly_limit = client.get("monthly_request_limit")
    if isinstance(daily_limit, int) and daily_limit >= 0 and day_used > daily_limit:
        _finalize_event(ev, "failed", error_code="QUOTA_EXCEEDED", error_message="Request blocked: daily quota would be exceeded.")
        _save("request_events.json", events)
        return _err("QUOTA_EXCEEDED", "daily quota exceeded", error_code="QUOTA_EXCEEDED")
    if isinstance(monthly_limit, int) and monthly_limit >= 0 and month_used > monthly_limit:
        _finalize_event(ev, "failed", error_code="QUOTA_EXCEEDED", error_message="Request blocked: monthly quota would be exceeded.")
        _save("request_events.json", events)
        return _err("QUOTA_EXCEEDED", "monthly quota exceeded", error_code="QUOTA_EXCEEDED")

    # Offline popular: use cached active videos sorted by recency, then filter by constraints.
    def _ok(m):
        if m.get("provider") != "pexels" or m.get("media_type") != "video" or m.get("status") != "active":
            return False
        w = m.get("width")
        h = m.get("height")
        d = m.get("duration_seconds")
        if min_width is not None and (not isinstance(w, int) or w < min_width):
            return False
        if min_height is not None and (not isinstance(h, int) or h < min_height):
            return False
        if min_duration is not None and (not isinstance(d, int) or d < min_duration):
            return False
        if max_duration is not None and (not isinstance(d, int) or d > max_duration):
            return False
        return True

    vids = [m for m in media if _ok(m)]
    def _sort_key(m):
        for f in ("last_synced_at", "updated_at", "created_at"):
            dt = _parse_iso(m.get(f))
            if dt:
                return dt
        return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
    vids.sort(key=_sort_key, reverse=True)

    total = len(vids)
    start = (page - 1) * per_page
    end = start + per_page
    page_items = vids[start:end]

    # touch last_synced_at for returned items
    changed = False
    for m in page_items:
        m["last_synced_at"] = _iso(nowdt)
        m["updated_at"] = _iso(nowdt)
        changed = True
    if changed:
        _save("media_items.json", media)

    _finalize_event(ev, "succeeded", upstream_status_code=200, response_bytes=None)
    _save("request_events.json", events)

    return {
        "page": page,
        "per_page": per_page,
        "total_results": total,
        "videos": page_items,
        "has_more": end < total,
        "next_page": (page + 1) if end < total else None,
    }

def getVideo(client_id, video_id, **_extra):
    import json, os, datetime, re, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0116000" if __import__("os").path.isdir("./environment_mix/0116000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        r = random.SystemRandom()
        return prefix + "".join(r.choice(alphabet) for _ in range(26))

    def _sanitize(obj):
        if obj is None:
            return None
        if isinstance(obj, (str, int, float, bool)):
            if isinstance(obj, str):
                return obj[:500]
            return obj
        if isinstance(obj, list):
            return [_sanitize(x) for x in obj][:200]
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                lk = str(k).lower()
                if "api_key" in lk or "authorization" in lk or "token" in lk:
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _sanitize(v)
            return out
        return str(obj)[:200]

    def _append_event(events, cid, key_id, params, upstream_endpoint=None, cached_media_id=None):
        now = _now()
        ev = {
            "id": _ulid("pex_req_"),
            "client_id": cid,
            "api_key_id": key_id,
            "tool_name": "getVideo",
            "status": "received",
            "parameters": _sanitize(params),
            "upstream_endpoint": upstream_endpoint,
            "upstream_status_code": None,
            "response_bytes": None,
            "latency_ms": None,
            "error_code": None,
            "error_message": None,
            "cached_media_id": cached_media_id,
            "cached_collection_id": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        events.append(ev)
        return ev

    def _finalize_event(events, ev_id, status, latency_ms, error_code=None, error_message=None, upstream_status_code=None, response_bytes=None, cached_media_id=None):
        now = _now()
        for ev in events:
            if ev.get("id") == ev_id:
                if ev.get("status") != "received":
                    return False
                if status not in ("succeeded", "failed"):
                    return False
                ev["status"] = status
                ev["latency_ms"] = int(latency_ms) if latency_ms is not None else None
                ev["error_code"] = error_code
                ev["error_message"] = _sanitize(error_message) if error_message is not None else None
                ev["upstream_status_code"] = upstream_status_code
                ev["response_bytes"] = int(response_bytes) if response_bytes is not None else None
                if cached_media_id is not None:
                    ev["cached_media_id"] = cached_media_id
                ev["updated_at"] = _iso(now)
                return True
        return False

    def _client_quotas_ok(events, cid, now_dt, daily_limit, monthly_limit):
        if not isinstance(daily_limit, int) or daily_limit < 0:
            daily_limit = 0
        if not isinstance(monthly_limit, int) or monthly_limit < 0:
            monthly_limit = 0
        day0 = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
        month0 = now_dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        daily = 0
        monthly = 0
        for ev in events:
            if ev.get("client_id") != cid:
                continue
            ts = _parse_iso(ev.get("created_at"))
            if ts is None:
                continue
            if ts >= day0:
                daily += 1
            if ts >= month0:
                monthly += 1
        if daily_limit and (daily + 1) > daily_limit:
            return False, "daily"
        if monthly_limit and (monthly + 1) > monthly_limit:
            return False, "monthly"
        return True, None

    def _envelope(video_row, ev):
        if video_row is None:
            return None
        return {
            "video": {
                "id": video_row.get("provider_media_id"),
                "cached_media_id": video_row.get("id"),
                "provider": video_row.get("provider"),
                "url": video_row.get("url"),
                "width": video_row.get("width"),
                "height": video_row.get("height"),
                "duration": video_row.get("duration_seconds"),
                "user": video_row.get("photographer_name"),
                "user_url": video_row.get("photographer_url"),
                "image": video_row.get("thumbnail_url"),
                "video_files": (video_row.get("assets") or {}),
                "attribution_required": video_row.get("attribution_required"),
                "last_synced_at": video_row.get("last_synced_at"),
                "created_at": video_row.get("created_at"),
                "updated_at": video_row.get("updated_at"),
                "status": video_row.get("status"),
            },
            "request_event_id": ev.get("id") if ev else None,
        }

    # ---- Validate inputs
    if not isinstance(client_id, str) or not re.match(r"^pex_cli_[0-9A-HJKMNP-TV-Z]{16,}$", client_id):
        return _err("VALIDATION_ERROR", "client_id is malformed")
    if not isinstance(video_id, int) or video_id < 1:
        return _err("VALIDATION_ERROR", "video_id must be a positive integer")

    # ---- Load datastore
    clients = _load("api_clients.json")
    keys = _load("api_keys.json")
    media = _load("media_items.json")
    events = _load("request_events.json")

    if isinstance(clients, dict) and "rows" in clients:
        clients = clients["rows"]
    if isinstance(keys, dict) and "rows" in keys:
        keys = keys["rows"]
    if isinstance(media, dict) and "rows" in media:
        media = media["rows"]
    if isinstance(events, dict) and "rows" in events:
        events = events["rows"]

    client = next((c for c in clients if c.get("id") == client_id), None)
    now_dt = _now()
    active_key = next((k for k in keys if k.get("client_id") == client_id and k.get("provider") == "pexels" and k.get("status") == "active"), None)

    ev = _append_event(events, client_id, active_key.get("id") if active_key else None, {"client_id": client_id, "video_id": video_id}, upstream_endpoint=f"/videos/videos/{video_id}")
    _save("request_events.json", events)

    daily_limit = client.get("daily_request_limit") if isinstance(client, dict) else 0
    monthly_limit = client.get("monthly_request_limit") if isinstance(client, dict) else 0
    ok_quota, which = _client_quotas_ok(events[:-1], client_id, now_dt, daily_limit if client else 0, monthly_limit if client else 0)
    if not ok_quota:
        _finalize_event(events, ev["id"], "failed", (time.time() - t0) * 1000, error_code="QUOTA_EXCEEDED", error_message=f"Request blocked: {which} quota would be exceeded.", upstream_status_code=None)
        _save("request_events.json", events)
        return _err("QUOTA_EXCEEDED", "quota exceeded", error_code="QUOTA_EXCEEDED")

    if client is None:
        _finalize_event(events, ev["id"], "failed", (time.time() - t0) * 1000, error_code="UNAUTHORIZED", error_message="Unknown client.", upstream_status_code=None)
        _save("request_events.json", events)
        return _err("UNAUTHORIZED", "unauthorized", error_code="UNAUTHORIZED")
    if client.get("status") != "active":
        _finalize_event(events, ev["id"], "failed", (time.time() - t0) * 1000, error_code="CLIENT_SUSPENDED", error_message="Client is not active; request blocked.", upstream_status_code=None)
        _save("request_events.json", events)
        return _err("UNAUTHORIZED", "client is not active", error_code="CLIENT_SUSPENDED")

    if active_key is None:
        _finalize_event(events, ev["id"], "failed", (time.time() - t0) * 1000, error_code="API_KEY_MISSING", error_message="No active Pexels API key configured for this client.", upstream_status_code=None)
        _save("request_events.json", events)
        return _err("UNAUTHORIZED", "no active api key for client", error_code="API_KEY_MISSING")

    row = next((m for m in media if m.get("provider") == "pexels" and m.get("media_type") == "video" and m.get("provider_media_id") == video_id), None)

    if row is not None and row.get("status") in ("active",):
        now = _now()
        row["last_synced_at"] = _iso(now)
        row["updated_at"] = _iso(now)
        _save("media_items.json", media)
        _finalize_event(events, ev["id"], "succeeded", (time.time() - t0) * 1000, upstream_status_code=200, response_bytes=None, cached_media_id=row.get("id"))
        _save("request_events.json", events)
        return _envelope(row, ev)

    if row is not None and row.get("status") in ("deleted", "tombstoned"):
        _finalize_event(events, ev["id"], "failed", (time.time() - t0) * 1000, error_code="UPSTREAM_NOT_FOUND", error_message="Video not available.", upstream_status_code=404, cached_media_id=row.get("id"))
        _save("request_events.json", events)
        return _err("NOT_FOUND", "video not found", error_code="UPSTREAM_NOT_FOUND")

    _finalize_event(events, ev["id"], "failed", (time.time() - t0) * 1000, error_code="UPSTREAM_NOT_FOUND", error_message="Upstream returned 404 for requested video.", upstream_status_code=404)
    _save("request_events.json", events)
    return _err("NOT_FOUND", "video not found", error_code="UPSTREAM_NOT_FOUND")

def getFeaturedCollections(client_id, page=None, per_page=None, **_extra):
    import json, os, datetime, time, uuid, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0116000" if __import__("os").path.isdir("./environment_mix/0116000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # helpers
    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"
    def _sanitize_params(p):
        if p is None:
            return None
        if isinstance(p, dict):
            out = {}
            for k, v in p.items():
                lk = str(k).lower()
                if "api_key" in lk or "authorization" in lk or "token" in lk:
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _sanitize_params(v)
            return out
        if isinstance(p, list):
            return [_sanitize_params(x) for x in p]
        return p
    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None
    def _same_day(a, b):
        return a.date() == b.date()
    def _same_month(a, b):
        return a.year == b.year and a.month == b.month

    # Validation
    if not isinstance(client_id, str) or not client_id.strip():
        return _err("VALIDATION_ERROR", "client_id is required and must be a non-empty string")
    if page is None:
        page = 1
    if per_page is None:
        per_page = 15
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if not isinstance(per_page, int) or per_page < 1 or per_page > 80:
        return _err("VALIDATION_ERROR", "per_page must be an integer in [1, 80]")

    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    collections = _load("collections.json")
    request_events = _load("request_events.json")

    client = next((c for c in api_clients if c.get("id") == client_id), None)
    # Create received request event first (business rule)
    ev_id = _new_id("pex_req")
    received = {
        "id": ev_id,
        "client_id": client_id,
        "api_key_id": None,
        "tool_name": "getFeaturedCollections",
        "status": "received",
        "parameters": _sanitize_params({"client_id": client_id, "page": page, "per_page": per_page}),
        "upstream_endpoint": "/v1/collections/featured",
        "upstream_status_code": None,
        "response_bytes": None,
        "latency_ms": None,
        "error_code": None,
        "error_message": None,
        "cached_media_id": None,
        "cached_collection_id": None,
        "created_at": now,
        "updated_at": now,
    }
    request_events.append(received)
    _save("request_events.json", request_events)

    def _finalize(status, upstream_status_code=None, response_bytes=None, error_code=None, error_message=None):
        nonlocal request_events
        # reload to reduce overwrite risk
        request_events = _load("request_events.json")
        ev = next((e for e in request_events if e.get("id") == ev_id), None)
        if not ev:
            return  # can't do much; avoid raising
        if ev.get("status") != "received":
            return
        ev["status"] = status
        ev["upstream_status_code"] = upstream_status_code
        ev["response_bytes"] = response_bytes
        ev["error_code"] = error_code
        ev["error_message"] = (error_message[:500] if isinstance(error_message, str) else error_message)
        ev["latency_ms"] = max(0, int((time.time() - t0) * 1000))
        ev["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("request_events.json", request_events)

    # Authn/Authz and prerequisites (client status and exactly one active key)
    if not client:
        _finalize("failed", upstream_status_code=None, error_code="NOT_FOUND", error_message="client_id not found")
        return _err("NOT_FOUND", "client_id not found")

    if client.get("status") != "active":
        _finalize("failed", upstream_status_code=None, error_code="CLIENT_SUSPENDED", error_message="client is not active")
        return _err("UNAUTHORIZED", "client is not active", error_code="CLIENT_SUSPENDED")

    active_keys = [k for k in api_keys if k.get("client_id") == client_id and k.get("provider") == "pexels" and k.get("status") == "active"]
    if len(active_keys) != 1:
        _finalize("failed", upstream_status_code=None, error_code="API_KEY_MISSING", error_message="active API key missing")
        return _err("UNAUTHORIZED", "active API key missing", error_code="API_KEY_MISSING")
    key = active_keys[0]

    # attach api_key_id to event
    request_events = _load("request_events.json")
    ev = next((e for e in request_events if e.get("id") == ev_id), None)
    if ev and ev.get("api_key_id") is None:
        ev["api_key_id"] = key.get("id")
        ev["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("request_events.json", request_events)

    # Quota enforcement (daily & monthly) against request_events for this client
    daily_limit = client.get("daily_request_limit")
    monthly_limit = client.get("monthly_request_limit")
    if not isinstance(daily_limit, int) or daily_limit < 0 or not isinstance(monthly_limit, int) or monthly_limit < 0:
        _finalize("failed", error_code="VALIDATION_ERROR", error_message="client quota limits misconfigured")
        return _err("CONFLICT", "client quota limits misconfigured")

    now_dt = datetime.datetime.utcnow()
    events_all = _load("request_events.json")
    client_events = [e for e in events_all if e.get("client_id") == client_id]
    day_count = 0
    month_count = 0
    for e in client_events:
        dt = _parse_dt(e.get("created_at"))
        if not dt:
            continue
        if _same_day(dt, now_dt):
            day_count += 1
        if _same_month(dt, now_dt):
            month_count += 1
    if daily_limit >= 0 and day_count > daily_limit:
        _finalize("failed", upstream_status_code=None, error_code="QUOTA_EXCEEDED", error_message="daily request limit exceeded")
        return _err("QUOTA_EXCEEDED", "daily request limit exceeded", error_code="QUOTA_EXCEEDED")
    if monthly_limit >= 0 and month_count > monthly_limit:
        _finalize("failed", upstream_status_code=None, error_code="QUOTA_EXCEEDED", error_message="monthly request limit exceeded")
        return _err("QUOTA_EXCEEDED", "monthly request limit exceeded", error_code="QUOTA_EXCEEDED")

    # Offline "upstream": deterministically generate a featured list for this client+page, then upsert into cache.
    def _featured_source(client_id, page, per_page):
        # stable pseudo list; provider_collection_id strings
        seed = hashlib.sha256(f"pexels-featured:{client_id}".encode("utf-8")).hexdigest()
        # create 200 deterministic collections
        out = []
        for i in range(1, 201):
            pid = f"featured_{seed[:6]}_{i:04d}"
            title = f"Featured Collection {i}"
            desc = None if i % 3 else f"A featured set #{i}."
            media_count = (i * 7) % 500
            out.append({
                "provider": "pexels",
                "provider_collection_id": pid,
                "title": title,
                "description": desc,
                "is_featured": True,
                "media_count": media_count,
            })
        start = (page - 1) * per_page
        end = start + per_page
        return out[start:end], len(out)

    items, total_available = _featured_source(client_id, page, per_page)

    # Upsert into collections cache (unique(provider, provider_collection_id))
    collections = _load("collections.json")
    media_items = _load("media_items.json")  # for cover references validation if needed later

    by_key = {(c.get("provider"), c.get("provider_collection_id")): c for c in collections}
    changed = False
    returned = []
    for it in items:
        k = (it["provider"], it["provider_collection_id"])
        row = by_key.get(k)
        if row:
            # update mutable fields, preserve cover_media_id unless set elsewhere
            row["title"] = it["title"]
            row["description"] = it["description"]
            row["is_featured"] = True
            row["media_count"] = it["media_count"]
            if row.get("status") in (None, ""):
                row["status"] = "active"
            if row.get("status") != "deleted":
                # don't resurrect deleted implicitly; only keep as-is unless not deleted
                row["status"] = row.get("status", "active")
            row["last_synced_at"] = now
            row["updated_at"] = now
            changed = True
        else:
            new_id = _new_id("pex_col")
            row = {
                "id": new_id,
                "provider": "pexels",
                "provider_collection_id": it["provider_collection_id"],
                "title": it["title"],
                "description": it["description"],
                "status": "active",
                "is_featured": True,
                "media_count": it["media_count"],
                "cover_media_id": None,
                "last_synced_at": now,
                "created_at": now,
                "updated_at": now,
            }
            collections.append(row)
            by_key[k] = row
            changed = True
        returned.append({
            "id": row.get("id"),
            "provider": row.get("provider"),
            "provider_collection_id": row.get("provider_collection_id"),
            "title": row.get("title"),
            "description": row.get("description"),
            "status": row.get("status"),
            "is_featured": row.get("is_featured"),
            "media_count": row.get("media_count"),
            "cover_media_id": row.get("cover_media_id"),
            "last_synced_at": row.get("last_synced_at"),
            "created_at": row.get("created_at"),
            "updated_at": row.get("updated_at"),
        })

    if changed:
        _save("collections.json", collections)

    # finalize event
    resp_bytes = len(json.dumps({"collections": returned}, ensure_ascii=False).encode("utf-8"))
    _finalize("succeeded", upstream_status_code=200, response_bytes=resp_bytes)

    total = total_available
    start = (page - 1) * per_page
    has_more = (start + len(returned)) < total
    return {
        "collections": returned,
        "page": page,
        "per_page": per_page,
        "total_results": total,
        "has_more": has_more,
        "next_page": (page + 1) if has_more else None,
    }

def getCollectionMedia(client_id, collection_id=None, provider_collection_id=None, type=None, page=None, per_page=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, uuid, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0116000" if __import__("os").path.isdir("./environment_mix/0116000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"
    def _sanitize_params(p):
        if p is None:
            return None
        if isinstance(p, dict):
            out = {}
            for k, v in p.items():
                lk = str(k).lower()
                if "api_key" in lk or "authorization" in lk or "token" in lk:
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _sanitize_params(v)
            return out
        if isinstance(p, list):
            return [_sanitize_params(x) for x in p]
        return p
    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None
    def _same_day(a, b):
        return a.date() == b.date()
    def _same_month(a, b):
        return a.year == b.year and a.month == b.month

    # Validation
    if not isinstance(client_id, str) or not client_id.strip():
        return _err("VALIDATION_ERROR", "client_id is required and must be a non-empty string")
    if type not in ("photos", "videos"):
        return _err("VALIDATION_ERROR", "type must be one of: photos, videos")
    if page is None:
        page = 1
    if per_page is None:
        per_page = 15
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if not isinstance(per_page, int) or per_page < 1 or per_page > 80:
        return _err("VALIDATION_ERROR", "per_page must be an integer in [1, 80]")
    if sort is not None and sort not in ("position", "added_at"):
        return _err("VALIDATION_ERROR", "sort must be one of: position, added_at")
    if order is not None and order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc")
    if collection_id is not None and (not isinstance(collection_id, str) or not collection_id.strip()):
        return _err("VALIDATION_ERROR", "collection_id must be a non-empty string when provided")
    if provider_collection_id is not None and (not isinstance(provider_collection_id, str) or not provider_collection_id.strip()):
        return _err("VALIDATION_ERROR", "provider_collection_id must be a non-empty string when provided")
    if not collection_id and not provider_collection_id:
        return _err("VALIDATION_ERROR", "either collection_id or provider_collection_id must be provided")
    if sort is None:
        sort = "position"
    if order is None:
        order = "asc"

    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    collections = _load("collections.json")
    media_items = _load("media_items.json")
    collection_media = _load("collection_media.json")
    request_events = _load("request_events.json")

    client = next((c for c in api_clients if c.get("id") == client_id), None)

    # Log received
    ev_id = _new_id("pex_req")
    upstream_endpoint = "/v1/collections/{id}"
    received = {
        "id": ev_id,
        "client_id": client_id,
        "api_key_id": None,
        "tool_name": "getCollectionMedia",
        "status": "received",
        "parameters": _sanitize_params({
            "client_id": client_id,
            "collection_id": collection_id,
            "provider_collection_id": provider_collection_id,
            "type": type,
            "page": page,
            "per_page": per_page,
            "sort": sort,
            "order": order,
        }),
        "upstream_endpoint": upstream_endpoint,
        "upstream_status_code": None,
        "response_bytes": None,
        "latency_ms": None,
        "error_code": None,
        "error_message": None,
        "cached_media_id": None,
        "cached_collection_id": None,
        "created_at": now,
        "updated_at": now,
    }
    request_events.append(received)
    _save("request_events.json", request_events)

    def _finalize(status, upstream_status_code=None, response_bytes=None, error_code=None, error_message=None, cached_collection_id_val=None):
        nonlocal request_events
        request_events = _load("request_events.json")
        ev = next((e for e in request_events if e.get("id") == ev_id), None)
        if not ev or ev.get("status") != "received":
            return
        ev["status"] = status
        ev["upstream_status_code"] = upstream_status_code
        ev["response_bytes"] = response_bytes
        ev["error_code"] = error_code
        ev["error_message"] = (error_message[:500] if isinstance(error_message, str) else error_message)
        if cached_collection_id_val is not None:
            ev["cached_collection_id"] = cached_collection_id_val
        ev["latency_ms"] = max(0, int((time.time() - t0) * 1000))
        ev["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("request_events.json", request_events)

    # Prerequisites
    if not client:
        _finalize("failed", error_code="NOT_FOUND", error_message="client_id not found")
        return _err("NOT_FOUND", "client_id not found")
    if client.get("status") != "active":
        _finalize("failed", error_code="CLIENT_SUSPENDED", error_message="client is not active")
        return _err("UNAUTHORIZED", "client is not active", error_code="CLIENT_SUSPENDED")

    active_keys = [k for k in api_keys if k.get("client_id") == client_id and k.get("provider") == "pexels" and k.get("status") == "active"]
    if len(active_keys) != 1:
        _finalize("failed", error_code="API_KEY_MISSING", error_message="active API key missing")
        return _err("UNAUTHORIZED", "active API key missing", error_code="API_KEY_MISSING")
    key = active_keys[0]

    request_events = _load("request_events.json")
    ev = next((e for e in request_events if e.get("id") == ev_id), None)
    if ev and ev.get("api_key_id") is None:
        ev["api_key_id"] = key.get("id")
        ev["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("request_events.json", request_events)

    # Quota checks
    daily_limit = client.get("daily_request_limit")
    monthly_limit = client.get("monthly_request_limit")
    if not isinstance(daily_limit, int) or daily_limit < 0 or not isinstance(monthly_limit, int) or monthly_limit < 0:
        _finalize("failed", error_code="VALIDATION_ERROR", error_message="client quota limits misconfigured")
        return _err("CONFLICT", "client quota limits misconfigured")

    now_dt = datetime.datetime.utcnow()
    events_all = _load("request_events.json")
    client_events = [e for e in events_all if e.get("client_id") == client_id]
    day_count = 0
    month_count = 0
    for e in client_events:
        dt = _parse_dt(e.get("created_at"))
        if not dt:
            continue
        if _same_day(dt, now_dt):
            day_count += 1
        if _same_month(dt, now_dt):
            month_count += 1
    if daily_limit >= 0 and day_count > daily_limit:
        _finalize("failed", error_code="QUOTA_EXCEEDED", error_message="daily request limit exceeded")
        return _err("QUOTA_EXCEEDED", "daily request limit exceeded", error_code="QUOTA_EXCEEDED")
    if monthly_limit >= 0 and month_count > monthly_limit:
        _finalize("failed", error_code="QUOTA_EXCEEDED", error_message="monthly request limit exceeded")
        return _err("QUOTA_EXCEEDED", "monthly request limit exceeded", error_code="QUOTA_EXCEEDED")

    # Resolve collection (by local id or provider id)
    collections = _load("collections.json")
    coll = None
    if collection_id:
        coll = next((c for c in collections if c.get("id") == collection_id), None)
    if not coll and provider_collection_id:
        coll = next((c for c in collections if c.get("provider") == "pexels" and c.get("provider_collection_id") == provider_collection_id), None)

    # Offline "upstream": if missing, create; then ensure media list cached and mappings maintained.
    def _upstream_collection(provider_collection_id):
        # fabricate basic collection metadata
        return {
            "provider": "pexels",
            "provider_collection_id": provider_collection_id,
            "title": f"Collection {provider_collection_id}",
            "description": None,
            "is_featured": False,
            "media_count": 120,
        }

    def _upstream_collection_media(provider_collection_id, media_type, page, per_page):
        # stable pseudo list of media for this collection
        seed = hashlib.sha256(f"pexels-collection:{provider_collection_id}:{media_type}".encode("utf-8")).hexdigest()
        total = 240
        start = (page - 1) * per_page
        end = min(total, start + per_page)
        out = []
        for idx in range(start, end):
            provider_media_id = int(seed[:8], 16) % 1_000_000_000
            provider_media_id = (provider_media_id + idx + 1) % 1_000_000_000
            if media_type == "photo":
                out.append({
                    "provider_media_id": provider_media_id,
                    "media_type": "photo",
                    "url": f"https://www.pexels.com/photo/{provider_media_id}/",
                    "width": 1920,
                    "height": 1280,
                    "duration_seconds": None,
                    "photographer_name": f"Creator {seed[8:12]}",
                    "photographer_url": f"https://www.pexels.com/@{seed[12:18]}/",
                    "avg_color": "#aabbcc",
                    "thumbnail_url": f"https://images.pexels.com/photos/{provider_media_id}/thumbnail.jpg",
                    "assets": {"src": {"original": f"https://images.pexels.com/photos/{provider_media_id}/pexels-photo-{provider_media_id}.jpeg"}},
                    "attribution_required": True,
                })
            else:
                out.append({
                    "provider_media_id": provider_media_id,
                    "media_type": "video",
                    "url": f"https://www.pexels.com/video/{provider_media_id}/",
                    "width": 1920,
                    "height": 1080,
                    "duration_seconds": (idx % 60) + 5,
                    "photographer_name": f"Creator {seed[8:12]}",
                    "photographer_url": f"https://www.pexels.com/@{seed[12:18]}/",
                    "avg_color": None,
                    "thumbnail_url": f"https://images.pexels.com/videos/{provider_media_id}/thumbnail.jpg",
                    "assets": {"video_files": [{"quality": "hd", "link": f"https://videos.pexels.com/video-files/{provider_media_id}/hd.mp4"}]},
                    "attribution_required": True,
                })
        # also return positions based on absolute index, and added_at as deterministic
        base_dt = datetime.datetime(2022, 1, 1, 0, 0, 0)
        enriched = []
        for j, m in enumerate(out):
            abs_idx = start + j
            added_at = (base_dt + datetime.timedelta(hours=abs_idx)).replace(microsecond=0).isoformat() + "Z"
            enriched.append((m, abs_idx, added_at))
        return enriched, total

    if not coll:
        # create it from upstream if provider_collection_id provided; else not found
        if not provider_collection_id:
            _finalize("failed", error_code="NOT_FOUND", error_message="collection not found")
            return _err("NOT_FOUND", "collection not found")
        meta = _upstream_collection(provider_collection_id)
        new_id = _new_id("pex_col")
        coll = {
            "id": new_id,
            "provider": "pexels",
            "provider_collection_id": meta["provider_collection_id"],
            "title": meta["title"],
            "description": meta["description"],
            "status": "active",
            "is_featured": meta["is_featured"],
            "media_count": meta["media_count"],
            "cover_media_id": None,
            "last_synced_at": now,
            "created_at": now,
            "updated_at": now,
        }
        collections.append(coll)
        _save("collections.json", collections)
    else:
        # refresh sync timestamp (upsert semantics)
        coll["last_synced_at"] = now
        coll["updated_at"] = now
        _save("collections.json", collections)

    _finalize("received", cached_collection_id_val=coll.get("id"))  # no-op if already not received; safe
    # Ensure event has cached_collection_id (reload + update if still received)
    request_events = _load("request_events.json")
    ev = next((e for e in request_events if e.get("id") == ev_id), None)
    if ev and ev.get("status") == "received" and not ev.get("cached_collection_id"):
        ev["cached_collection_id"] = coll.get("id")
        ev["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("request_events.json", request_events)

    want_media_type = "photo" if type == "photos" else "video"
    upstream_rows, total_available = _upstream_collection_media(coll["provider_collection_id"], want_media_type, page, per_page)

    # Upsert media_items and maintain collection_media mappings (unique collection_id, media_id),
    # removals represented by status transition to removed.
    media_items = _load("media_items.json")
    collection_media = _load("collection_media.json")

    mi_by_key = {(m.get("provider"), m.get("provider_media_id"), m.get("media_type")): m for m in media_items}
    cm_by_key = {(cm.get("collection_id"), cm.get("media_id")): cm for cm in collection_media}
    touched_cm_keys = set()
    changed_mi = False
    changed_cm = False

    returned_media = []
    for m, pos, added_at in upstream_rows:
        mk = ("pexels", m["provider_media_id"], m["media_type"])
        row = mi_by_key.get(mk)
        if row:
            # update metadata; ensure active
            row["status"] = "active"
            row["url"] = m.get("url")
            row["width"] = m.get("width")
            row["height"] = m.get("height")
            row["duration_seconds"] = m.get("duration_seconds")
            row["photographer_name"] = m.get("photographer_name")
            row["photographer_url"] = m.get("photographer_url")
            row["avg_color"] = m.get("avg_color")
            row["thumbnail_url"] = m.get("thumbnail_url")
            row["assets"] = m.get("assets")
            row["attribution_required"] = bool(m.get("attribution_required", True))
            row["last_synced_at"] = now
            row["updated_at"] = now
            changed_mi = True
        else:
            row = {
                "id": _new_id("pex_med"),
                "provider": "pexels",
                "provider_media_id": int(m["provider_media_id"]),
                "media_type": m["media_type"],
                "status": "active",
                "url": m.get("url"),
                "width": m.get("width"),
                "height": m.get("height"),
                "duration_seconds": m.get("duration_seconds"),
                "photographer_name": m.get("photographer_name"),
                "photographer_url": m.get("photographer_url"),
                "avg_color": m.get("avg_color"),
                "thumbnail_url": m.get("thumbnail_url"),
                "assets": m.get("assets"),
                "attribution_required": bool(m.get("attribution_required", True)),
                "last_synced_at": now,
                "created_at": now,
                "updated_at": now,
            }
            media_items.append(row)
            mi_by_key[mk] = row
            changed_mi = True

        cmk = (coll["id"], row["id"])
        touched_cm_keys.add(cmk)
        cm = cm_by_key.get(cmk)
        if cm:
            # if previously removed, do not allow transition back (schema transitions removed:[])
            # so we keep it removed and still return media as cached media item, but mapping remains removed
            if cm.get("status") == "active":
                cm["position"] = pos
                cm["added_at"] = added_at
                cm["updated_at"] = now
                changed_cm = True
        else:
            # create mapping (schema implies lifecycle field status; but fields list omitted; still required by lifecycle)
            cm = {
                "id": _new_id("pex_cmi"),
                "collection_id": coll["id"],
                "media_id": row["id"],
                "position": pos,
                "added_at": added_at,
                "created_at": now,
                "updated_at": now,
                "status": "active",
            }
            collection_media.append(cm)
            cm_by_key[cmk] = cm
            changed_cm = True

        returned_media.append((row, cm_by_key.get(cmk)))

    # Handle removals: any active mapping for this collection not in touched set becomes removed
    for cm in collection_media:
        if cm.get("collection_id") != coll["id"]:
            continue
        cmk = (cm.get("collection_id"), cm.get("media_id"))
        if cmk not in touched_cm_keys and cm.get("status") == "active":
            cm["status"] = "removed"
            cm["updated_at"] = now
            changed_cm = True

    if changed_mi:
        _save("media_items.json", media_items)
    if changed_cm:
        _save("collection_media.json", collection_media)

    # Build cached results list and apply requested sort/order over cached results for this page
    # Return only mappings that are active and match media_type
    # Use cached mappings; but we just populated current page positions. Sorting is over cached set for collection.
    collection_media = _load("collection_media.json")
    media_items = _load("media_items.json")
    mi_by_id = {m.get("id"): m for m in media_items}

    all_pairs = []
    for cm in collection_media:
        if cm.get("collection_id") != coll["id"]:
            continue
        if cm.get("status") != "active":
            continue
        m = mi_by_id.get(cm.get("media_id"))
        if not m:
            continue
        if m.get("media_type") != want_media_type:
            continue
        all_pairs.append((cm, m))

    reverse = (order == "desc")
    if sort == "position":
        def keyfn(x):
            v = x[0].get("position")
            return (v is None, v if v is not None else 10**18, x[1].get("id") or "")
    else:
        def keyfn(x):
            dt = _parse_dt(x[0].get("added_at")) or datetime.datetime.min
            return (dt, x[1].get("id") or "")
    all_pairs.sort(key=keyfn, reverse=reverse)

    total = len(all_pairs)
    start = (page - 1) * per_page
    end = start + per_page
    page_pairs = all_pairs[start:end]

    results = []
    for cm, m in page_pairs:
        results.append({
            "media": {
                "id": m.get("id"),
                "provider": m.get("provider"),
                "provider_media_id": m.get("provider_media_id"),
                "media_type": m.get("media_type"),
                "status": m.get("status"),
                "url": m.get("url"),
                "width": m.get("width"),
                "height": m.get("height"),
                "duration_seconds": m.get("duration_seconds"),
                "photographer_name": m.get("photographer_name"),
                "photographer_url": m.get("photographer_url"),
                "avg_color": m.get("avg_color"),
                "thumbnail_url": m.get("thumbnail_url"),
                "assets": m.get("assets"),
                "attribution_required": m.get("attribution_required"),
                "last_synced_at": m.get("last_synced_at"),
                "created_at": m.get("created_at"),
                "updated_at": m.get("updated_at"),
            },
            "mapping": {
                "id": cm.get("id"),
                "collection_id": cm.get("collection_id"),
                "media_id": cm.get("media_id"),
                "position": cm.get("position"),
                "added_at": cm.get("added_at"),
                "status": cm.get("status"),
                "created_at": cm.get("created_at"),
                "updated_at": cm.get("updated_at"),
            }
        })

    has_more = end < total
    resp_bytes = len(json.dumps({"media": results}, ensure_ascii=False).encode("utf-8"))
    _finalize("succeeded", upstream_status_code=200, response_bytes=resp_bytes, cached_collection_id_val=coll.get("id"))

    return {
        "collection": {
            "id": coll.get("id"),
            "provider": coll.get("provider"),
            "provider_collection_id": coll.get("provider_collection_id"),
            "title": coll.get("title"),
            "description": coll.get("description"),
            "status": coll.get("status"),
            "is_featured": coll.get("is_featured"),
            "media_count": coll.get("media_count"),
            "cover_media_id": coll.get("cover_media_id"),
            "last_synced_at": coll.get("last_synced_at"),
            "created_at": coll.get("created_at"),
            "updated_at": coll.get("updated_at"),
        },
        "type": type,
        "page": page,
        "per_page": per_page,
        "sort": sort,
        "order": order,
        "total_results": total,
        "has_more": has_more,
        "next_page": (page + 1) if has_more else None,
        "items": results,
    }

def getCaller(client_id=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0116000" if __import__("os").path.isdir("./environment_mix/0116000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"
    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None
    def _same_day(a, b):
        return a.date() == b.date()
    def _same_month(a, b):
        return a.year == b.year and a.month == b.month

    # Validate optional client_id if present (pattern)
    if client_id is not None:
        if not isinstance(client_id, str):
            return _err("VALIDATION_ERROR", "client_id must be a string")
        import re
        if not re.match(r"^pex_cli_[0-9A-HJKMNP-TV-Z]{16,}$", client_id):
            return _err("VALIDATION_ERROR", "client_id is malformed")

    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    request_events = _load("request_events.json")

    # Resolve identity:
    # - If client_id provided, use it if exists.
    # - Else pick any active client that has exactly one active key (a workable combination).
    client = None
    key = None
    if client_id:
        client = next((c for c in api_clients if c.get("id") == client_id), None)
        if client:
            active_keys = [k for k in api_keys if k.get("client_id") == client.get("id") and k.get("provider") == "pexels" and k.get("status") == "active"]
            if len(active_keys) == 1:
                key = active_keys[0]
    else:
        for c in api_clients:
            if c.get("status") != "active":
                continue
            active_keys = [k for k in api_keys if k.get("client_id") == c.get("id") and k.get("provider") == "pexels" and k.get("status") == "active"]
            if len(active_keys) == 1:
                client = c
                key = active_keys[0]
                break

    # Log received event; if no client resolved, we cannot satisfy constraints requiring client_id.
    # In that case, refuse UNAUTHORIZED without logging request_events (since schema requires client_id).
    if not client:
        return _err("UNAUTHORIZED", "no valid caller identity could be resolved")

    ev_id = _new_id("pex_req")
    received = {
        "id": ev_id,
        "client_id": client.get("id"),
        "api_key_id": key.get("id") if key else None,
        "tool_name": "getCaller",
        "status": "received",
        "parameters": {"client_id": client_id} if client_id is not None else {},
        "upstream_endpoint": None,
        "upstream_status_code": None,
        "response_bytes": None,
        "latency_ms": None,
        "error_code": None,
        "error_message": None,
        "cached_media_id": None,
        "cached_collection_id": None,
        "created_at": now,
        "updated_at": now,
    }
    request_events.append(received)
    _save("request_events.json", request_events)

    def _finalize(status, error_code=None, error_message=None, response_bytes=None):
        nonlocal request_events
        request_events = _load("request_events.json")
        ev = next((e for e in request_events if e.get("id") == ev_id), None)
        if not ev or ev.get("status") != "received":
            return
        ev["status"] = status
        ev["error_code"] = error_code
        ev["error_message"] = (error_message[:500] if isinstance(error_message, str) else error_message)
        ev["response_bytes"] = response_bytes
        ev["latency_ms"] = max(0, int((time.time() - t0) * 1000))
        ev["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("request_events.json", request_events)

    # Compute quota usage from request_events
    now_dt = datetime.datetime.utcnow()
    events_all = _load("request_events.json")
    client_events = [e for e in events_all if e.get("client_id") == client.get("id")]
    daily_used = 0
    monthly_used = 0
    for e in client_events:
        dt = _parse_dt(e.get("created_at"))
        if not dt:
            continue
        if _same_day(dt, now_dt):
            daily_used += 1
        if _same_month(dt, now_dt):
            monthly_used += 1

    daily_limit = client.get("daily_request_limit")
    monthly_limit = client.get("monthly_request_limit")
    caller = {
        "client": {
            "id": client.get("id"),
            "display_name": client.get("display_name"),
            "status": client.get("status"),
            "daily_request_limit": daily_limit,
            "monthly_request_limit": monthly_limit,
            "created_at": client.get("created_at"),
            "updated_at": client.get("updated_at"),
        },
        "credential": None if not key else {
            "id": key.get("id"),
            "client_id": key.get("client_id"),
            "provider": key.get("provider"),
            "api_key_last4": key.get("api_key_last4"),
            "status": key.get("status"),
            "activated_at": key.get("activated_at"),
            "revoked_at": key.get("revoked_at"),
            "created_at": key.get("created_at"),
            "updated_at": key.get("updated_at"),
        },
        "scopes": ["pexels:read", "pexels:write:keys"],
        "quota": {
            "daily": {"used": daily_used, "limit": daily_limit},
            "monthly": {"used": monthly_used, "limit": monthly_limit},
        }
    }

    resp_bytes = len(json.dumps(caller, ensure_ascii=False).encode("utf-8"))
    _finalize("succeeded", response_bytes=resp_bytes)
    return caller
